/* Тема: ставим data-theme на <html> одним действием, без :has() и без каскада transition */
(function(){
  var cb=document.getElementById('yh-theme-toggle'); if(!cb) return;
  var root=document.documentElement;
  if(root.getAttribute('data-theme')==='light') cb.checked=true;
  function apply(){
    root.classList.add('yh-switching');
    root.setAttribute('data-theme',cb.checked?'light':'dark');
    requestAnimationFrame(function(){requestAnimationFrame(function(){root.classList.remove('yh-switching');});});
  }
  cb.addEventListener('change',apply);
  if(cb.checked) root.setAttribute('data-theme','light');
})();


