    if(active){var dx=px-m.cx,dy=py-m.cy,d=Math.sqrt(dx*dx+dy*dy),k=Math.max(0,1-d/240);lift-=k*k*22;c.style.scale=String(1+k*.1);}else{c.style.scale='1';}
    c.style.translate='0 '+lift+'px';
